# Constants for astronomical calculations
AU = 149.6e6  # 1 Astronomical Unit in kilometers

# Planetary data with orbital parameters (circular approximation)
PLANETARY_DATA = [
    {
        'name': 'Mercury',
        'radius': 0.387,  # AU (semi-major axis)
        'period': 88,     # Earth days (orbital period)
        'color': '#A9A9A9',
        'mass': 3.3011e23  # kg
    },
    {
        'name': 'Venus',
        'radius': 0.723,
        'period': 224.7,
        'color': '#FFD700',
        'mass': 4.8675e24
    },
    {
        'name': 'Earth',
        'radius': 1.0,
        'period': 365.25,
        'color': '#00BFFF',
        'mass': 5.972e24
    },
    {
        'name': 'Mars',
        'radius': 1.524,
        'period': 687,
        'color': '#FF4500',
        'mass': 6.4171e23
    },
    {
        'name': 'Jupiter',
        'radius': 5.203,
        'period': 4331,
        'color': '#FFA500',
        'mass': 1.8982e27
    }
]

def calculate_position(time_days, planet):
    """
    Calculate planet position using circular orbit approximation
    Returns (x, y) coordinates in AU
    """
    angular_velocity = 2 * math.pi / planet['period']  # radians per day
    theta = angular_velocity * time_days
    return (
        planet['radius'] * math.cos(theta),
        planet['radius'] * math.sin(theta)
    )

def generate_simulation_data(timestamp=None):
    """
    Generate simulation data for current time
    Returns JSON-compatible structure
    """
    if timestamp is None:
        timestamp = datetime.now().timestamp()

    days_since_epoch = (timestamp - datetime(2023, 1, 1).timestamp()) / (24 * 3600)

    simulation_data = {
        'timestamp': timestamp,
        'planets': []
    }

    for planet in PLANETARY_DATA:
        x, y = calculate_position(days_since_epoch, planet)

        simulation_data['planets'].append({
            'name': planet['name'],
            'color': planet['color'],
            'position': {
                'x': x * AU,  # Convert AU to kilometers
                'y': y * AU
            },
            'orbital_radius': planet['radius'] * AU
        })

    return simulation_data

# Example usage: Generate current positions
if __name__ == "__main__":
    data = generate_simulation_data()
    with open('solar_system_data.json', 'w') as f:
        json.dump(data, f, indent=2)
