// Waveform parameters
let offset = 0;
const period = 100; // Pixels per wave cycle
let lastPulseTime = 0;
const pulseDuration = 300; // ms for full scale cycle

function drawWaveform(currentTime) {
// Clear canvas
ctx.clearRect(0, 0, canvas.width, canvas.height);

// Draw baseline
ctx.beginPath();
ctx.moveTo(0, 16);
ctx.lineTo(canvas.width, 16);
ctx.strokeStyle = '#f00';
ctx.lineWidth = 1;
ctx.stroke();

// Draw triangle waveform
ctx.beginPath();
ctx.strokeStyle = '#00ff00';
ctx.lineWidth = 3;

for (let x = 0; x < canvas.width; x++) {
const waveX = x + offset;
const t = (waveX % period) / period;
const y = t < 0.5 
? 2 * t * 32 
: 32 - 2 * (t - 0.5) * 32;

if (x === 0) {
ctx.moveTo(x, y);
} else {
ctx.lineTo(x, y);
}
}
ctx.stroke();

// Dot animation logic
const dotX = (offset + 10) % canvas.width; // Offset from waveform for visibility
const waveX = dotX + offset;
const t = (waveX % period) / period;
const dotY = t < 0.5 
? 2 * t * 32 
: 32 - 2 * (t - 0.5) * 32;

// Calculate scale factor (triangle wave)
let scale = 1;
if (t < 0.02 || t > 0.98 || (t > 0.48 && t < 0.52)) {
// Trigger pulse at valley (t≈0/1) or peak (t≈0.5)
const elapsed = currentTime - lastPulseTime;
if (elapsed < pulseDuration) {
const phase = elapsed / pulseDuration;
if (phase < 0.5) {
scale = 1 + (phase * 2) * 3; // Scale up
} else {
scale = 4 - ((phase - 0.5) * 2) * 3; // Scale down
}
} else {
lastPulseTime = currentTime;
}
} else if (!lastPulseTime) {
lastPulseTime = currentTime;
}

// Draw dot
ctx.beginPath();
ctx.arc(dotX, dotY, 4 * scale, 0, Math.PI * 2);
ctx.fillStyle = '#000';
ctx.fill();

// Update offset (slower scrolling)
offset += 0.2;

requestAnimationFrame(drawWaveform);
}

// Start animation with timestamp parameter
requestAnimationFrame(drawWaveform);
</script>
